@import url('https://fonts.googleapis.com/css2?family=League+Spartan:wght@400;500;600;700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* James Bond — tuxedo black and white, gunbarrel gold precision */
.theme-james-bond {
  --bg: oklch(0.159 0 0);
  --surface: oklch(0.200 0 0);
  --surface-2: oklch(0.248 0 0);
  --fg: oklch(0.956 0.006 84.6);
  --fg-muted: oklch(0.644 0.008 88.7);
  --accent: oklch(0.956 0.006 84.6);
  --accent-fg: oklch(0.159 0 0);
  --accent-2: oklch(0.691 0.088 80.7);
  --line: oklch(1 0 0 / 16%);
  --success: oklch(0.550 0.052 144.8);
  --warning: oklch(0.691 0.088 80.7);
  --danger: oklch(0.420 0.148 26.4);
  --radius: 0px;
  --radius-sm: 0px;
  --radius-lg: 0px;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "League Spartan", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.02em;
  --label-transform: uppercase;
  --label-tracking: 0.22em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-james-bond h1,
.theme-james-bond h2,
.theme-james-bond h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-james-bond { background-image: radial-gradient(circle at 88% 12%, transparent 58px, oklch(1 0 0 / 5%) 58px 60px, transparent 60px 74px, oklch(1 0 0 / 5%) 74px 76px, transparent 76px 90px, oklch(1 0 0 / 4%) 90px 92px, transparent 92px); }
.theme-james-bond h1, .theme-james-bond h2 { text-transform: uppercase; font-weight: 700; }
.theme-james-bond h1::after { content: ""; display: block; height: 2px; width: 5rem; margin-top: 0.7rem; background: var(--accent-2); }
.theme-james-bond button { letter-spacing: 0.14em; }

/* alt-mode — the day brief: ivory shirt white, tuxedo-black ink, gold bar intact */
.theme-james-bond.alt-mode {
  --bg: oklch(0.962 0.005 85.0);
  --surface: oklch(0.988 0.003 85.0);
  --surface-2: oklch(0.920 0.007 85.0);
  --fg: oklch(0.185 0 0);
  --fg-muted: oklch(0.470 0.006 88.0);
  --accent: oklch(0.200 0 0);
  --accent-fg: oklch(0.962 0.005 85.0);
  --accent-2: oklch(0.600 0.095 80.7);
  --line: oklch(0 0 0 / 16%);
  --success: oklch(0.480 0.060 144.8);
  --warning: oklch(0.620 0.100 80.7);
  --danger: oklch(0.450 0.150 26.4);
  --shadow-1: 0 1px 3px oklch(0 0 0 / 12%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 14%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 18%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent-2) 55%, transparent);
  background-image: radial-gradient(circle at 88% 12%, transparent 58px, oklch(0 0 0 / 5%) 58px 60px, transparent 60px 74px, oklch(0 0 0 / 5%) 74px 76px, transparent 76px 90px, oklch(0 0 0 / 4%) 90px 92px, transparent 92px);
}


/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
